/* ============================================
   AVATAR COMPONENT
   User profile image with initials fallback
   ============================================ */

.ds-avatar {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-pill); /* 999px */
  background-color: var(--color-bg-container-secondary);
  flex-shrink: 0;
}

/* ============================================
   SIZES
   ============================================ */

.ds-avatar--sm {
  width: 32px;
  height: 32px;
}

.ds-avatar--md {
  width: 40px;
  height: 40px;
}

.ds-avatar--lg {
  width: 56px;
  height: 56px;
}

/* ============================================
   IMAGE
   ============================================ */

.ds-avatar__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  border-radius: var(--radius-pill);
}

/* ============================================
   INITIALS FALLBACK
   ============================================ */

.ds-avatar__initials {
  font-family: var(--font-paragraph-emphasis-family);
  font-weight: var(--font-paragraph-emphasis-weight);
  color: var(--color-text-primary);
  line-height: 1;
  user-select: none;
}

.ds-avatar--sm .ds-avatar__initials {
  font-size: 12px;
}

.ds-avatar--md .ds-avatar__initials {
  font-size: 14px;
}

.ds-avatar--lg .ds-avatar__initials {
  font-size: 18px;
}

/* ============================================
   ICON FALLBACK
   ============================================ */

.ds-avatar__icon {
  color: var(--color-icon-secondary);
  line-height: 1;
}

.ds-avatar--sm .ds-avatar__icon {
  --icon-size: var(--icon-size-500);
}

.ds-avatar--md .ds-avatar__icon {
  --icon-size: var(--icon-size-600);
}

.ds-avatar--lg .ds-avatar__icon {
  --icon-size: var(--icon-size-800);
}

/* ============================================
   STATUS INDICATOR
   ============================================ */

.ds-avatar__status {
  position: absolute;
  bottom: 0;
  right: 0;
  border-radius: var(--radius-pill);
  border: 2px solid var(--color-bg-page-primary);
}

.ds-avatar--sm .ds-avatar__status {
  width: 10px;
  height: 10px;
}

.ds-avatar--md .ds-avatar__status {
  width: 12px;
  height: 12px;
}

.ds-avatar--lg .ds-avatar__status {
  width: 14px;
  height: 14px;
}

.ds-avatar__status--online {
  background-color: var(--color-status-positive-border);
}

.ds-avatar__status--away {
  background-color: var(--color-status-warning-border);
}

.ds-avatar__status--offline {
  background-color: var(--color-bg-container-border);
}

.ds-avatar__status--busy {
  background-color: var(--color-status-error-border);
}

'use client';

import { useState } from 'react';
import './Avatar.css';
import '../../fonts/material-symbols.css';

export interface AvatarProps {
  /** Image source URL */
  src?: string;
  /** Alt text for the image */
  alt?: string;
  /** User's name — used for initials fallback */
  name?: string;
  /** Avatar size */
  size?: 'sm' | 'md' | 'lg';
  /** Online status indicator */
  status?: 'online' | 'away' | 'offline' | 'busy';
  /** Additional CSS classes */
  className?: string;
}

/**
 * Avatar component for user profile images.
 * Falls back to initials derived from the name prop,
 * or a person icon when neither image nor name is provided.
 */
export const Avatar = ({
  src,
  alt,
  name,
  size = 'md',
  status,
  className = '',
}: AvatarProps) => {
  const [imgError, setImgError] = useState(false);

  const baseClass = 'ds-avatar';
  const sizeClass = `${baseClass}--${size}`;

  const classes = [baseClass, sizeClass, className].filter(Boolean).join(' ');

  const getInitials = (fullName: string): string => {
    const parts = fullName.trim().split(/\s+/);
    if (parts.length === 1) return parts[0][0].toUpperCase();
    return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
  };

  const showImage = src && !imgError;
  const showInitials = !showImage && name;
  const showIcon = !showImage && !name;

  const label = alt || name || 'User avatar';

  return (
    <span className={classes} role="img" aria-label={label}>
      {showImage && (
        <img
          className={`${baseClass}__image`}
          src={src}
          alt={alt || name || ''}
          onError={() => setImgError(true)}
        />
      )}

      {showInitials && (
        <span className={`${baseClass}__initials`} aria-hidden="true">
          {getInitials(name!)}
        </span>
      )}

      {showIcon && (
        <span
          className={`${baseClass}__icon material-symbols-rounded`}
          aria-hidden="true"
        >
          person
        </span>
      )}

      {status && (
        <span
          className={`${baseClass}__status ${baseClass}__status--${status}`}
          // A bare <span> has no role, and aria-label is prohibited on roles
          // that provide no semantics. role="img" is what this dot actually is.
          role="img"
          aria-label={status}
        />
      )}
    </span>
  );
};
